package ru.cherdakmd.chrdkregister;

import com.google.gson.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import ru.cherdakmd.chrdkregister.api.*;
import java.io.IOException;
import java.nio.file.*;
import java.util.*;
import java.util.logging.Logger;
import static org.junit.jupiter.api.Assertions.*;

class ClaimBankTest {
    @TempDir Path dir;
    final UUID lineage=UUID.randomUUID(),buyer=UUID.randomUUID(),seller=UUID.randomUUID();
    final Logger log=Logger.getAnonymousLogger();
    BankStore load() {var b=new BankStore(dir,log);b.load();return b;}
    BankStore funded() {var b=load();b.deposit(buyer,"Buyer",100);b.deposit(seller,"Seller",10);assertTrue(b.registerClaimSource(lineage));return b;}
    ClaimExchange trade(long seq) {return new ClaimExchange(UUID.randomUUID(),lineage,seq,"land-sale",Map.of(buyer,-30L,seller,27L),ClaimExchange.hash("frozen domain"));}
    @Test void allAccountsAndReceiptAreOneDurablePublication() {var b=funded();var t=trade(1);assertEquals(ClaimExchange.Status.COMMITTED,b.commitClaim(t));b=load();assertEquals(70,b.balance(buyer));assertEquals(37,b.balance(seller));assertEquals(30,b.account(buyer).withdrawn);assertEquals(37,b.account(seller).deposited);assertEquals(ClaimExchange.Status.COMMITTED,b.claimStatus(t));}
    @Test void retryAfterSpendingDoesNotDebitOrCreditAgain() {var b=funded();var t=trade(1);b.commitClaim(t);b.withdraw(seller,37);b.flush();assertEquals(ClaimExchange.Status.COMMITTED,load().commitClaim(t));assertEquals(0,load().balance(seller));assertEquals(70,load().balance(buyer));}
    @Test void alteredSkippedOrOldSequenceIsConflict() {var b=funded();var t=trade(1);b.commitClaim(t);assertEquals(ClaimExchange.Status.CONFLICT,b.commitClaim(trade(1)));assertEquals(ClaimExchange.Status.CONFLICT,b.commitClaim(trade(3)));b.commitClaim(trade(2));assertEquals(ClaimExchange.Status.CONFLICT,b.commitClaim(t));}
    @Test void capAndShortageNeverPartiallyMoveAccounts() {var b=funded();b.setBalance(seller,"Seller",BankStore.MAX_BALANCE);var t=trade(1);assertEquals(ClaimExchange.Status.MISSING,b.commitClaim(t));assertEquals(100,b.balance(buyer));b.setBalance(seller,"Seller",10);b.setBalance(buyer,"Buyer",1);assertEquals(ClaimExchange.Status.MISSING,b.commitClaim(t));assertEquals(10,b.balance(seller));}
    @Test void unknownUuidIsUnavailableNotAFreeAccount() {var b=funded();var t=new ClaimExchange(UUID.randomUUID(),lineage,1,"land-buy",Map.of(UUID.randomUUID(),0L),ClaimExchange.hash("domain"));assertEquals(ClaimExchange.Status.UNAVAILABLE,b.commitClaim(t));}
    @Test void ownerNativeReservationBlocksTheWholeSettlement() {var b=funded();assertNotNull(b.prepareCash(buyer,"Buyer",BankCash.Kind.DEPOSIT,9,9,-1,9,"before","after"));assertEquals(ClaimExchange.Status.UNAVAILABLE,b.commitClaim(trade(1)));assertEquals(10,b.balance(seller));}
    @Test void missingOrWrongLineageCannotBecomeASafeMissingResult() {var b=load();assertEquals(ClaimExchange.Status.UNAVAILABLE,b.claimStatus(trade(1)));assertTrue(b.registerClaimSource(UUID.randomUUID()));assertFalse(b.registerClaimSource(lineage));assertEquals(ClaimExchange.Status.UNAVAILABLE,b.commitClaim(trade(1)));}
    @Test void zeroMoneyDebtAndReleaseTransitionsStillHaveDomainReceipt() {var b=funded();var t=new ClaimExchange(UUID.randomUUID(),lineage,1,"land-upkeep",Map.of(),ClaimExchange.hash("release chunk"));assertEquals(ClaimExchange.Status.COMMITTED,b.commitClaim(t));assertEquals(ClaimExchange.Status.COMMITTED,load().claimStatus(t));}
    @Test void beforeRenameFailureLeavesBothAccountsAndSequenceUntouched() throws Exception {funded();Files.createDirectory(dir.resolve("bank.json.tmp"));var b=load();var t=trade(1);assertEquals(ClaimExchange.Status.UNAVAILABLE,b.commitClaim(t));assertFalse(b.available());b.flush();assertEquals(100,load().balance(buyer));assertEquals(10,load().balance(seller));assertEquals(ClaimExchange.Status.MISSING,load().claimStatus(t));}
    @Test void afterRenameAmbiguityNeverSeparatesReceiptFromAccounts() {funded();var b=new BankStore(dir,log,()->{throw new IOException("uncertain");});b.load();var t=trade(1);assertEquals(ClaimExchange.Status.UNAVAILABLE,b.commitClaim(t));b.flush();assertEquals(ClaimExchange.Status.COMMITTED,load().claimStatus(t));assertEquals(70,load().balance(buyer));assertEquals(37,load().balance(seller));}
    @Test void legacyClaimsImportIsForcedAndIdempotentByNameAndUuid() {var b=load();assertTrue(b.importLegacyClaims(buyer,"Buyer",13));assertEquals(13,load().balance(buyer));assertTrue(load().importLegacyClaims(buyer,"buyer",13));assertFalse(load().importLegacyClaims(seller,"Buyer",13));assertEquals(13,load().balance(buyer));}
    @Test void ambiguousLegacyImportKeepsItsReceiptOnDisk() {var b=new BankStore(dir,log,()->{throw new IOException("uncertain");});assertFalse(b.importLegacyClaims(buyer,"Buyer",13));b.flush();assertEquals(13,load().balance(buyer));assertTrue(load().importLegacyClaims(buyer,"Buyer",13));assertEquals(13,load().balance(buyer));}
    @Test void nativeFundingDepositsBlockChangeOnceBeforeAnyDomainAcceptance() throws Exception {var b=funded();var p=b.prepareCash(buyer,"Buyer",BankCash.Kind.CLAIM_FUND,9,9,-1,105,"before","after");assertNotNull(p);var bag=new InventoryTransferTest.Bag(buyer);assertEquals(InventoryTransfer.Decision.APPLIED,BankCash.recover(b,buyer,bag));assertEquals(109,load().balance(buyer));BankCash.recover(load(),buyer,bag);assertEquals(109,load().balance(buyer));assertEquals(1,bag.applies);assertEquals(ClaimExchange.Status.MISSING,load().claimStatus(trade(1)));}
    @Test void fundingAfterWithoutNonceCannotCreateMoney() throws Exception {var b=funded();b.prepareCash(buyer,"Buyer",BankCash.Kind.CLAIM_FUND,9,9,-1,105,"before","after");var bag=new InventoryTransferTest.Bag(buyer);bag.state="after";assertEquals(InventoryTransfer.Decision.CONFLICT,BankCash.recover(b,buyer,bag));assertEquals(100,load().balance(buyer));}
    @Test void invalidFundingBoundsRefuseWithoutReservation() {var b=funded();assertNull(b.prepareCash(buyer,"Buyer",BankCash.Kind.CLAIM_FUND,1,9,-1,105,"before","after"));assertNull(b.prepareCash(buyer,"Buyer",BankCash.Kind.CLAIM_FUND,9,9,-1,99,"before","after"));assertFalse(b.cashLocked(buyer));}
    @Test void schemaSixUpgradesButCannotHideClaimReceipts() throws Exception {var b=funded();var json=JsonParser.parseString(Files.readString(b.file())).getAsJsonObject();json.addProperty("schema",6);json.remove("claimSettlements");Files.writeString(b.file(),json.toString());assertTrue(load().available());assertEquals(ClaimExchange.Status.COMMITTED,load().commitClaim(trade(1)));json=JsonParser.parseString(Files.readString(b.file())).getAsJsonObject();json.addProperty("schema",6);Files.writeString(b.file(),json.toString());assertFalse(load().available());}
    @Test void malformedReceiptNumbersAndRemovedTableQuarantineWithoutRewrite() throws Exception {var b=funded();b.commitClaim(trade(1));String original=Files.readString(b.file());for(String number:List.of("\"1\"","1.5","9223372036854775808")) {var json=JsonParser.parseString(original).getAsJsonObject();json.getAsJsonObject("claimSettlements").getAsJsonObject(lineage.toString()).add("sequence",JsonParser.parseString(number));String bad=json.toString();Files.writeString(b.file(),bad);var broken=load();assertFalse(broken.available());broken.flush();assertEquals(bad,Files.readString(b.file()));}var json=JsonParser.parseString(original).getAsJsonObject();json.remove("claimSettlements");Files.writeString(b.file(),json.toString());assertFalse(load().available());}
    @Test void requestDeltasAreImmutableAndArithmeticIsBounded() {var deltas=new HashMap<UUID,Long>();deltas.put(buyer,-30L);var t=new ClaimExchange(UUID.randomUUID(),lineage,1,"land-buy",deltas,ClaimExchange.hash("domain"));deltas.clear();assertTrue(t.valid());assertEquals(-30,t.deltas().get(buyer));assertThrows(UnsupportedOperationException.class,()->t.deltas().clear());assertFalse(new ClaimExchange(t.transaction(),lineage,Long.MAX_VALUE,"land-buy",Map.of(),t.effectHash()).valid());}
}
